@startuml

class Movie {
  + title : string
}

class Order {
  + date : date
}

class Card {
  + balance : float
}

class User {
  + name : string
}

class Subscriber {
  + subscription_id : string
}

User "1" -- "*" Order : places
Subscriber "1" -- "1" Card : has
Subscriber "0..*" -- "*" Movie : hires
User "0..*" -- "*" Movie : buys
Order "*" -- "1" Movie : contains
Movie "0..1" -- "0..1" Movie : ordered

@enduml

